t=$1; shift; args=(); for s in "$@"; do ffmpeg -v error -y -ss $s -i ${t}.mp4 -frames:v 1 -vf scale=240:-1 c_o_$s.jpg; ffmpeg -v error -y -ss $s -i ${t}_edit.mp4 -frames:v 1 -vf scale=240:-1 c_e_$s.jpg; ffmpeg -v error -y -i c_o_$s.jpg -i c_e_$s.jpg -filter_complex vstack c_$s.jpg; args+=(-i c_$s.jpg); done; ffmpeg -v error -y "${args[@]}" -filter_complex hstack=$# cmp_$t.jpg; rm c_*.jpg
